  r = I({ ph: 7.34, pco2: 60, hco3: 31, na: 140, cl: 97, alb: 4 });
  check('abg: chronic respiratory acidosis (HCO3 +3.5 per 10)', r.comp === 'chronic' && r.disorders[0] === 'Respiratory acidosis, chronic');
  r = I({ ph: 7.30, pco2: 60, hco3: 28.5, na: 140, cl: 100, alb: 4 });
  check('abg: acute on chronic respiratory acidosis', r.comp === 'between');
  r = I({ ph: 7.55, pco2: 25, hco3: 21, na: 140, cl: 107, alb: 4 });
