  r = I({ ph: 7.15, pco2: 50, hco3: 17, na: 140, cl: 105, alb: 4 });
  check('abg: mixed metabolic and respiratory acidosis', r.primary === 'Mixed metabolic and respiratory acidosis' && r.comp === null && has(r, 'Respiratory acidosis'));
  r = I({ ph: 7.32, pco2: 20, hco3: 10, na: 140, cl: 100, alb: 4 });
