  r = I({ ph: 7.33, pco2: 35, hco3: 18, na: 140, cl: 92, alb: 4 });
  check('abg: delta ratio 3 (18 ÷ 6) adds a metabolic alkalosis', close(r.deltaRatio, 3) && has(r, 'Metabolic alkalosis'));
  r = I({ ph: 7.40, pco2: 40, hco3: 24, na: 140, cl: 104, alb: 4 });
  check('abg: normal gas', r.primary === 'None' && r.disorders[0] === 'No acid-base disorder found');
  r = I({ ph: 7.32, pco2: 28, hco3: 14, na: 140, cl: 100, alb: 4, glucose: 5, urea: 5, osm: 320, lactate: 1.5 });
  check('abg: osmolar gap 30 (2 × 140 + 5 + 5 = 290), lactate not raised', r.osmCalc === 290 && r.osmGap === 30 && has(r, 'Raised osmolar gap') && r.steps.some((s) => s.title === 'Lactate' && s.text.includes('not lactate')));
  check('abg: pH that disagrees is flagged', I({ ph: 7.10, pco2: 17, hco3: 6, na: 135, cl: 98, alb: 4 }).steps[0].tone === 'warn');
  const bad = (f) => { try { f(); return false; } catch { return true; } };
  check('abg: bad input refused', bad(() => I({ ph: 9, pco2: 40, hco3: 24, na: 140, cl: 104, alb: 4 })) && bad(() => I({ ph: 7.4, pco2: 40, hco3: 24, na: 140, cl: 104, alb: 4, osm: 300 })));
